				copy[i + 1] !== copy[left + 1] ||
				copy[i + 2] !== copy[left + 2] ||
				copy[i] !== copy[up] ||
				copy[i + 1] !== copy[up + 1] ||
				copy[i + 2] !== copy[up + 2];
